import os
import json
from google.cloud import documentai_v1 as documentai

def extract_key_values(payload, config=None):
    config = config or {}
    client = documentai.DocumentProcessorServiceClient()
    processor_name = config.get("processor_name", os.getenv("GOOGLE_DOCUMENT_AI_PROCESSOR_NAME", "projects/your-project/locations/us/processors/abc123"))
    mime_type = config.get("mime_type", "application/pdf")

    # Read the file into memory
    if isinstance(payload, str):
        with open(payload, "rb") as file:
            content = file.read()
    else:
        content = payload

    # Configure the process request
    request = {
        "name": processor_name,
        "raw_document": {
            "content": content,
            "mime_type": mime_type,
        },
    }

    # Process the document
    result = client.process_document(request=request)

    # Extract key-value pairs from the response
    document = result.document
    key_values = []

    for page in document.pages:
        for form_field in page.form_fields:
            field_name = form_field.field_name.text_anchor.content
            field_value = form_field.field_value.text_anchor.content
            key_values.append({
                "key": field_name,
                "value": field_value,
                "confidence": form_field.field_name.confidence
            })

    return key_values
